using System.Threading.Tasks;using UnityEngine; [CreateAssetMenu(menuName="Under The Horizon/Interaction Actions/Character")] public sealed class CharacterInteractionAction:InteractionAction { [SerializeField]private DialogueSequence dialogue;public override async Task<InteractionResult> ExecuteAsync(InteractionContext context){if(dialogue==null||context.Narrative==null)return new(false);await context.Narrative.PlayAsync(dialogue);return InteractionResult.Completed;} }
